CREATE TEMPORARY VIEW dws_request_advv_base_${grass_region_without_quote} AS
SELECT
    filter(feature_groups, value -> value not like '%#%' and value != 'Livestream') as feature_groups
    ,user_id
    ,platform

    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(ads_imp_cnt) as ads_imp_cnt
    ,sum(ads_click_cnt) as ads_click_cnt
    ,sum(broad_advv_cost) as broad_advv_cost
    ,sum(if(array_contains(main_product_types, 'roi2.0'), broad_advv_cost, 0)) as roi2_broad_advv_cost
FROM
    srdi_mart.dws_sr_data_warehouse_ads_request_benchmark_advv_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND array_contains(product_types, '__ALL__')
    AND (
        revenue_usd > 0
        or ads_gmv_usd > 0
        or broad_gmv_usd > 0
        or ads_order_cnt > 0
        or ads_broad_order_cnt > 0
        or ads_imp_cnt > 0
        or ads_click_cnt > 0
        or broad_advv_cost > 0
    )
GROUP BY 1,2,3
;

