    user_id
    ,item_id
    ,order_id
    ,platform
    ,coalesce(is_ads, false) as is_ads
    ,scenario_tag
    ,sum(gmv) as gmv
    ,sum(pc2_gmv) pc2_gmv
from
    srdi_mart.dws_sr_data_warehouse_platform_order_benchmark_1d
    lateral view explode(filter(dedup_scenario_tags, value -> value like 'DA_%' or value = 'dpm module Global Search business line Search')) as scenario_tag
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and user_id > 0
    and (gmv > 0 or pc2_gmv > 0)
group by 1,2,3,4,5,6
;

