CREATE TEMPORARY VIEW dws_gmv_995_${grass_region_without_quote} AS
select
    user_id
    ,platform
    ,a.is_ads
    ,scenario_tag
    ,coalesce(b.category_tag, 'low gmv') as category_tag
    ,if(gmv <= gmv_995pct, gmv, gmv_995pct) as gmv_995_v2
    ,if(pc2_gmv <= pc2_gmv_995pct, pc2_gmv, pc2_gmv_995pct) as pc2_gmv_995_v2
from
    dws_order_benchmark_${grass_region_without_quote} as a
left join
    dim_item_${grass_region_without_quote} as b
on
    a.item_id = b.item_id
inner join
    gmv995_v2_outlier_${grass_region_without_quote} as c
on
    coalesce(b.category_tag, 'low gmv') = c.category_tag
    and a.is_ads = cast(c.is_ads as boolean)
    and a.scenario_tag = c.feature_group
;

