CREATE TEMPORARY VIEW scenario_tag_level_advv_${grass_region_without_quote} AS
SELECT
    user_id
    ,platform
    ,true as is_ads
    ,case
        when feature_group = 'Search' then 'dpm module Global Search business line Search'
        when feature_group = 'Cart Unify' then 'DA_Cart_Unify'
        when feature_group = 'Order Detail Page YMAL' then 'DA_odp_ymal-order_detail'
        when feature_group = 'My Purchase Page YMAL' then 'DA_mpp_ymal-order_list'
        when feature_group in ('Game', '__ALL__') then feature_group
        when feature_group = 'others' then 'Others'
        else concat('DA_', feature_group)
    end as scenario_tag
    ,SUM(revenue_usd) AS revenue_usd
    ,SUM(ads_gmv_usd) AS ads_gmv_usd
    ,SUM(broad_gmv_usd) AS broad_gmv_usd
    ,SUM(ads_order_cnt) AS ads_order_cnt
    ,SUM(ads_broad_order_cnt) AS ads_broad_order_cnt
    ,SUM(ads_imp_cnt) AS ads_imp_cnt
    ,SUM(ads_click_cnt) AS ads_click_cnt
    ,SUM(broad_advv_cost) AS broad_advv_cost
    ,SUM(roi2_broad_advv_cost) AS roi2_broad_advv_cost
FROM
    dws_request_advv_base_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(if(size(feature_groups) = 1, array_union(feature_groups, array('others')), feature_groups)) AS feature_group
GROUP BY 1,2,4
;

