CREATE TEMPORARY VIEW scenario_tag_level_data_${grass_region_without_quote} AS
SELECT
    coalesce(t1.user_id, t2.user_id) as user_id
    ,coalesce(t1.platform, t2.platform) as platform
    ,coalesce(t1.is_ads, t2.is_ads) as is_ads
    ,coalesce(t1.scenario_tag, t2.scenario_tag) as scenario_tag

    ,coalesce(t1.imp_cnt, 0) as imp_cnt
    ,coalesce(t1.click_cnt, 0) as click_cnt
    ,coalesce(t1.item_imp_cnt, 0) as item_imp_cnt
    ,coalesce(t1.item_click_cnt, 0) as item_click_cnt
    ,coalesce(t1.ppv_cnt, 0) as ppv_cnt
    ,coalesce(t1.ppv_cnt_exclude_isback, 0) as ppv_cnt_exclude_isback
    ,coalesce(t1.cart_cnt, 0) as cart_cnt
    ,coalesce(t1.order_cnt, 0) as order_cnt
    ,coalesce(t1.gmv, 0) as gmv
    ,coalesce(t1.atc_same_day_order_cnt, 0) as atc_same_day_order_cnt
    ,coalesce(t1.atc_within_3day_order_cnt, 0) as atc_within_3day_order_cnt
    ,coalesce(t1.atc_same_day_gmv, 0) as atc_same_day_gmv
    ,coalesce(t1.atc_within_3day_gmv, 0) as atc_within_3day_gmv
    ,coalesce(t1.omni_imp_cnt, 0) as omni_imp_cnt
    ,coalesce(t1.omni_click_cnt, 0) as omni_click_cnt
    ,coalesce(t1.pc2_gmv, 0) as pc2_gmv
    ,coalesce(t2.revenue_usd, 0) as revenue_usd
    ,coalesce(t2.ads_gmv_usd, 0) as ads_gmv_usd
    ,coalesce(t2.broad_gmv_usd, 0) as broad_gmv_usd
    ,coalesce(t2.ads_order_cnt, 0) as ads_order_cnt
    ,coalesce(t2.ads_broad_order_cnt, 0) as ads_broad_order_cnt
    ,coalesce(t2.ads_imp_cnt, 0) as ads_imp_cnt
    ,coalesce(t2.ads_click_cnt, 0) as ads_click_cnt
    ,coalesce(t2.broad_advv_cost, 0) as broad_advv_cost
    ,coalesce(t2.roi2_broad_advv_cost, 0) as roi2_broad_advv_cost
    ,coalesce(t3.high_gmv_995_v2, 0) as high_gmv_995_v2
    ,coalesce(t3.low_gmv_995_v2, 0) as low_gmv_995_v2
    ,coalesce(t3.high_pc2_gmv_995_v2, 0) as high_pc2_gmv_995_v2
    ,coalesce(t3.low_pc2_gmv_995_v2, 0) as low_pc2_gmv_995_v2
FROM
    scenario_tag_level_dwm_platform_${grass_region_without_quote} as t1
FULL OUTER JOIN
    scenario_tag_level_advv_${grass_region_without_quote} as t2
ON
    coalesce(t1.user_id, -1) = coalesce(t2.user_id, -1)
    and coalesce(t1.platform, 'NULL') = coalesce(t2.platform, 'NULL')
    and t1.is_ads = t2.is_ads
    and t1.scenario_tag = t2.scenario_tag
LEFT JOIN
    dws_gmv_995_agg_${grass_region_without_quote} as t3
ON
    coalesce(t1.user_id, -1) = coalesce(t3.user_id, -1)
    and coalesce(t1.platform, 'NULL') = coalesce(t3.platform, 'NULL')
    and t1.is_ads = t3.is_ads
    and t1.scenario_tag = t3.scenario_tag
;

