INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_platform_user_level_benchmark_1d
PARTITION (grass_region = ${grass_region}, local_date = ${local_date})
-- data without feature_detail and scenario_tag dimension
SELECT
    user_id
    ,null as device_id
    ,platform
    ,is_ads
    ,'__ALL__' AS feature_detail
    ,scenario_tag
    ,imp_cnt
    ,click_cnt
    ,item_imp_cnt
    ,item_click_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
    ,omni_imp_cnt
    ,omni_click_cnt
    ,pc2_gmv

    ,revenue_usd
    ,ads_gmv_usd
    ,broad_gmv_usd
    ,ads_order_cnt
    ,ads_broad_order_cnt
    ,ads_imp_cnt
    ,ads_click_cnt
    ,broad_advv_cost
    ,roi2_broad_advv_cost

    ,high_gmv_995_v2
    ,low_gmv_995_v2
    ,high_pc2_gmv_995_v2
    ,low_pc2_gmv_995_v2
FROM scenario_tag_level_data_${grass_region_without_quote}

UNION ALL
SELECT
    user_id
    ,null as device_id
    ,platform
    ,is_ads
    ,feature_detail
    ,scenario_tag
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(item_imp_cnt) AS item_imp_cnt
    ,SUM(item_click_cnt) AS item_click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(ppv_cnt_exclude_isback) AS ppv_cnt_exclude_isback
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(atc_same_day_order_cnt) AS atc_same_day_order_cnt
    ,SUM(atc_within_3day_order_cnt) AS atc_within_3day_order_cnt
    ,SUM(atc_same_day_gmv) AS atc_same_day_gmv
    ,SUM(atc_within_3day_gmv) AS atc_within_3day_gmv
    ,SUM(omni_imp_cnt) AS omni_imp_cnt
    ,SUM(omni_click_cnt) AS omni_click_cnt
    ,SUM(pc2_gmv) AS pc2_gmv
    ,0 AS revenue_usd
    ,0 AS ads_gmv_usd
    ,0 AS broad_gmv_usd
    ,0 AS ads_order_cnt
    ,0 AS ads_broad_order_cnt
    ,0 AS ads_imp_cnt
    ,0 AS ads_click_cnt
    ,0 AS broad_advv_cost
    ,0 AS roi2_broad_advv_cost
    ,0 AS high_gmv_995_v2
    ,0 AS low_gmv_995_v2
    ,0 AS high_pc2_gmv_995_v2
    ,0 AS low_pc2_gmv_995_v2
FROM scenario_tag_feature_detail_level_data_${grass_region_without_quote}
GROUP BY user_id, platform, is_ads, feature_detail, scenario_tag
